from pathlib import Path

def repl(t,old,new,label):
    if old in t:return t.replace(old,new,1)
    if new in t:return t
    raise SystemExit(f'{label} anchor missing')

# Inspector
p=Path('app/src/InspectorPanel.tsx'); t=p.read_text()
