t=repl(t,"setDraft({label:entity.label||entity.id,materialId:entity.materialId,sectionId:entity.sectionId,A:entity.A,I:entity.I,releases:{rz1:false,rz2:false,...entity.releases},fiberHinges:{rz1:{...defaultFiberHinge,...entity.fiberHinges?.rz1},rz2:{...defaultFiberHinge,...entity.fiberHinges?.rz2}},uniform:clone(uniform)});","setDraft({label:entity.label||entity.id,materialId:entity.materialId,sectionId:entity.sectionId,A:entity.A,I:entity.I,releases:{rz1:false,rz2:false,...entity.releases},fiberHinges:{rz1:{...defaultFiberHinge,...entity.fiberHinges?.rz1},rz2:{...defaultFiberHinge,...entity.fiberHinges?.rz2}},distributedPlasticity:{...defaultDistributedPlasticity,...entity.distributedPlasticity},uniform:clone(uniform)});",'inspector draft')
t=repl(t,"  const applyElement=()=>{const p=clone(project),e=p.elements.find((x:any)=>x.id===entity.id),fiberHinges={rz1:normalizedHinge(draft.fiberHinges?.rz1),rz2:normalizedHinge(draft.fiberHinges?.rz2)};Object.assign(e,{label:draft.label,materialId:draft.materialId,sectionId:draft.sectionId,A:Math.max(1e-12,num(draft.A)),I:e.type==='frame2d'?Math.max(1e-16,num(draft.I)):0,releases:{...draft.releases},fiberHinges});","  const normalizedDistributed=(raw:any)=>({enabled:!!raw?.enabled,integrationPoints:[3,5].includes(Math.round(num(raw?.integrationPoints,5)))?Math.round(num(raw?.integrationPoints,5)):5,nFibers:Math.max(8,Math.min(400,Math.round(num(raw?.nFibers,80)))),hardeningRatio:Math.max(1e-6,Math.min(.25,Math.abs(num(raw?.hardeningRatio,.01))))});\n  const applyElement=()=>{const p=clone(project),e=p.elements.find((x:any)=>x.id===entity.id),distributedPlasticity=normalizedDistributed(draft.distributedPlasticity),fiberHinges=distributedPlasticity.enabled?{rz1:{...normalizedHinge(draft.fiberHinges?.rz1),enabled:false},rz2:{...normalizedHinge(draft.fiberHinges?.rz2),enabled:false}}:{rz1:normalizedHinge(draft.fiberHinges?.rz1),rz2:normalizedHinge(draft.fiberHinges?.rz2)};Object.assign(e,{label:draft.label,materialId:draft.materialId,sectionId:draft.sectionId,A:Math.max(1e-12,num(draft.A)),I:e.type==='frame2d'?Math.max(1e-16,num(draft.I)):0,releases:distributedPlasticity.enabled?{rz1:false,rz2:false}:{...draft.releases},fiberHinges,distributedPlasticity});",'inspector apply head')
t=repl(t,"e.rotationalSprings={rz1:e.rotationalSprings?.rz1??null,rz2:e.rotationalSprings?.rz2??null};for(const key of ['rz1','rz2'])if(fiberHinges[key].enabled){e.releases[key]=false;e.rotationalSprings[key]=null}if(fiberHinges.rz1.enabled||fiberHinges.rz2.enabled)p.settings={...(p.settings||{}),analysisType:'corotational'};","e.rotationalSprings=distributedPlasticity.enabled?{rz1:null,rz2:null}:{rz1:e.rotationalSprings?.rz1??null,rz2:e.rotationalSprings?.rz2??null};for(const key of ['rz1','rz2'])if(fiberHinges[key].enabled){e.releases[key]=false;e.rotationalSprings[key]=null}if(fiberHinges.rz1.enabled||fiberHinges.rz2.enabled||distributedPlasticity.enabled)p.settings={...(p.settings||{}),analysisType:'corotational'};",'inspector apply compat')
